"""Value-level mutations of a valid request; must always exit 0 with valid JSON."""
import json, random, subprocess, sys, copy
sys.path.insert(0,'/app/tmp/work')
import gen3, gen5

rng = random.Random(4242)
bad = 0
counts = {}
WRONG = [1.0, True, False, None, "1", [], {}, 0, -1, 1e400 if False else 99999999999999999999, "$", "eq"]
def mutate(obj, path):
    node = obj
    for k in path[:-1]:
        node = node[k]
    node[path[-1]] = rng.choice(WRONG)

def paths(obj, pre=()):
    out = []
    if isinstance(obj, dict):
        for k,v in obj.items():
            out.append(pre+(k,))
            out += paths(v, pre+(k,))
    elif isinstance(obj, list):
        for i,v in enumerate(obj):
            out.append(pre+(i,))
            out += paths(v, pre+(i,))
    return out

for i in range(700):
    req = (gen3.gen if i%2 else gen5.gen)(random.Random(i))
    ps = paths(req)
    if not ps: continue
    m = copy.deepcopy(req)
    for _ in range(rng.randint(1,3)):
        try:
            mutate(m, rng.choice(ps))
        except Exception:
            pass
    # also sometimes drop/add keys
    if rng.random()<0.3 and isinstance(m, dict):
        if rng.random()<0.5:
            m['bogus'] = 1
        else:
            m.pop(rng.choice(list(m.keys())), None)
    text = json.dumps(m)
    p = subprocess.run(['/app/submission/run.sh'], input=text.encode(), capture_output=True, cwd='/app/submission')
    if p.returncode != 0:
        bad += 1; print('NONZERO', p.returncode, p.stderr.decode()[:500]); 
        open('/app/tmp/work/jf_%d.json'%i,'w').write(text)
        if bad>3: break
        continue
    try:
        r = json.loads(p.stdout.decode())
    except Exception as e:
        bad += 1; print('BADOUT', e, p.stdout[:200]); break
    key = r.get('error','ok') if isinstance(r,dict) else 'other'
    counts[key] = counts.get(key,0)+1
    if key == 'ok':
        if set(r.keys()) != {'version','classes','queries'}: bad+=1; print('keys',r.keys())
    elif key not in ('E_JSON','E_SCHEMA','E_LIMIT'):
        bad+=1; print('weird error', r)
print('jsonfuzz done bad=',bad,counts)
PYEOF
cd /app/tmp/work && timeout 1700 python3 jsonfuzz.py 2>&1 | tail -6
